@Component("organization-handler")
@ProcessingGroup("organization-processing-group")
public class OrganizationEventHandler {
	
	// core constructor
	OrganizationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOrganizationEvent
     */
    @EventHandler
    public void handle( CreateOrganizationEvent event) {
        entityManager.persist(new Organization(event.getOrganizationId(), event.getName(), event.getLegalName(), event.getJurisdiction(), event.getIndustrySector(), event.getGovernanceBodies(), event.getPolicies(), event.getRisks(), event.getThirdParties(), event.getRecordsRepositories(), event.getDataProcessingActivities(), event.getCompliancePrograms(), event.getAuditPrograms(), event.getBusinessUnits(), event.getMatters(), event.getDataBreaches()));
    }

    /*
     * @param	event UpdateOrganizationEvent
     */
    @EventHandler
    public Organization handle( UpdateOrganizationEvent event) {
    	entityManager.merge(new Organization(event.getOrganizationId(), event.getName(), event.getLegalName(), event.getJurisdiction(), event.getIndustrySector(), event.getGovernanceBodies(), event.getPolicies(), event.getRisks(), event.getThirdParties(), event.getRecordsRepositories(), event.getDataProcessingActivities(), event.getCompliancePrograms(), event.getAuditPrograms(), event.getBusinessUnits(), event.getMatters(), event.getDataBreaches()));
    }
    
    /*
     * @param	event DeleteOrganizationEvent
     */
    @EventHandler
    public void on( DeleteOrganizationEvent event) {
    	Organization entity = new Organization();
   
    	// ------------------------------------------
    	// apply the OrganizationId
    	// ------------------------------------------
    	entity.setOrganizationId( event.getOrganizationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OrganizationRepository organizationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OrganizationEventHandler.class.getName());

}
